  "onboarding.body": "\uADF8\uB8F9\uC740 \uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4 \uC0AC\uC774\uB4DC\uBC14 \uC704\uC5D0 \uCD94\uAC00\uB418\uB294 \uB808\uC774\uC5B4\uC785\uB2C8\uB2E4. \uC138\uC158\uC744 \uADF8\uB8F9\uC5D0 \uBC30\uC815\uD574\uB3C4 \uC18C\uC18D \uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4\uB098 \uB85C\uADF8\uB294 \uBC14\uB00C\uC9C0 \uC54A\uC73C\uBA70, \uD504\uB9AC \uADF8\uB8F9\uC5D0\uC11C \uC138\uC158\uC774 \uD45C\uC2DC\uB418\uB294 \uC704\uCE58\uB9CC \uBC14\uB01D\uB2C8\uB2E4. \uC138\uC158\uC744 \uADF8\uB8F9\uC73C\uB85C \uB04C\uC5B4\uB2E4 \uB193\uACE0, \uADF8\uB8F9 \uD5E4\uB354\uB97C \uB04C\uC5B4 \uC21C\uC11C\uB97C \uBC14\uAFB8\uAC70\uB098 \uC911\uCCA9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
