  "toast.forkUnavailable": "\uC774 \uC138\uC158\uC740 \uBD84\uAE30\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4(\uC644\uB8CC\uB41C \uD134\uC774 \uC5C6\uAC70\uB098 \uC561\uC138\uC2A4 \uAD8C\uD55C\uC774 \uC5C6\uC74C)",
  "config.destructiveConfirmBody": "AI\uAC00 \uADF8\uB8F9\uC744 \uC0AD\uC81C\uD560 \uC218 \uC788\uAC8C \uB418\uBA70, \uC0AD\uC81C\uB294 UI\uC5D0\uC11C \uB418\uB3CC\uB9B4 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. AI\uC758 \uADF8\uB8F9 \uC0AD\uC81C\uAC00 \uBA85\uD655\uD788 \uD544\uC694\uD560 \uB54C\uB9CC \uD65C\uC131\uD654\uD558\uC138\uC694.",
